def load_bank():
 out=[];current=None
 for line in BLOCKS.strip().splitlines():
  if line.startswith('#'):
   current={'qa':[],'mcq':[]};out.append(current);continue
  if not line.strip():continue
  row=line.split('|');kind=row.pop(0)
  if kind=='Q':
   assert len(row)==3,row
   q,a,src=row;field,anchor=src.split(':',1);current['qa'].append({'q':q,'a':a,'basis':field,'anchor':anchor})
  else:
   assert kind=='M' and len(row)==8,row
   q,a,w1,w2,w3,why,hint,src=row;field,anchor=src.split(':',1);current['mcq'].append({'q':q,'a':a,'wrong':[w1,w2,w3],'why':why,'hint':hint,'basis':field,'anchor':anchor})
 assert len(out)==40
 return out
from expanded_learning import expand
BANK=expand(load_bank())
